// SPDX-License-Identifier: MIT
pragma solidity 0.8.38;
contract Receiver {}
contract ImmutableReview { uint256 public number; uint256 public immutable cap; address public immutable owner; bytes4 public immutable tag; int8 public immutable signedLimit; bool public immutable enabled; Receiver public immutable receiver; constructor(uint256 c,address o,bytes4 t,int8 s,bool e,Receiver r) { cap=c;owner=o;tag=t;signedLimit=s;enabled=e;receiver=r; } function store(uint256 value) external { require(msg.sender==owner);require(value<=cap);number=value; } function repeatCap() external view returns(uint256,uint256) { return (cap,cap); } }
